-- Re-label United States jobs that were stored as "other" because the city had a state code
-- ("San Francisco, CA") or the country only appeared in the structured locations.
UPDATE jobs SET country = 'united-states'
WHERE country = 'other'
  AND (
    json_extract(payload, '$.locations[0].country') IN ('United States', 'USA', 'US')
    OR (
      coalesce(json_extract(payload, '$.locations[0].country'), '') IN ('', 'United States', 'USA', 'US')
      AND (json_extract(payload, '$.location_raw') GLOB '*, AL' OR json_extract(payload, '$.location_raw') GLOB '*, AL[^A-Za-z]*' OR json_extract(payload, '$.location_raw') GLOB '*,AL[^A-Za-z]*' OR json_extract(payload, '$.location_raw') GLOB '*,AL' OR json_extract(payload, '$.location_raw') GLOB '*, AK' OR json_extract(payload, '$.location_raw') GLOB '*, AK[^A-Za-z]*' OR json_extract(payload, '$.location_raw') GLOB '*,AK[^A-Za-z]*' OR json_extract(payload, '$.location_raw') GLOB '*,AK' OR json_extract(payload, '$.location_raw') GLOB '*, AZ' OR json_extract(payload, '$.location_raw') GLOB '*, AZ[^A-Za-z]*' OR json_extract(payload, '$.location_raw') GLOB '*,AZ[^A-Za-z]*' OR json_extract(payload, '$.location_raw') GLOB '*,AZ' OR json_extract(payload, '$.location_raw') GLOB '*, AR' OR json_extract(payload, '$.location_raw') GLOB '*, AR[^A-Za-z]*' OR json_extract(payload, '$.location_raw') GLOB '*,AR[^A-Za-z]*' OR json_extract(payload, '$.location_raw') GLOB '*,AR' OR json_extract(payload, '$.location_raw') GLOB '*, CA' OR json_extract(payload, '$.location_raw') GLOB '*, CA[^A-Za-z]*' OR json_extract(payload, '$.location_raw') GLOB '*,CA[^A-Za-z]*' OR json_extract(payload, '$.location_raw') GLOB '*,CA' OR json_extract(payload, '$.location_raw') GLOB '*, CO' OR json_extract(payload, '$.location_raw') GLOB '*, CO[^A-Za-z]*' OR json_extract(payload, '$.location_raw') GLOB '*,CO[^A-Za-z]*' OR json_extract(payload, '$.location_raw') GLOB '*,CO' OR json_extract(payload, '$.location_raw') GLOB '*, CT' OR json_extract(payload, '$.location_raw') GLOB '*, CT[^A-Za-z]*' OR json_extract(payload, '$.location_raw') GLOB '*,CT[^A-Za-z]*' OR json_extract(payload, '$.location_raw') GLOB '*,CT' OR json_extract(payload, '$.location_raw') GLOB '*, DC' OR json_extract(payload, '$.location_raw') GLOB '*, DC[^A-Za-z]*' OR json_extract(payload, '$.location_raw') GLOB '*,DC[^A-Za-z]*' OR json_extract(payload, '$.location_raw') GLOB '*,DC' OR json_extract(payload, '$.location_raw') GLOB '*, DE' 